package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.GrantTypesJsonVO;

class GrantTypesJsonValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of grant types json of oauth client")
  void test_grant_types_json_value_holder_assign_plain_value() {
    Object holder = new Object();
    GrantTypesJsonValueHolder<Object> value = new GrantTypesJsonValueHolder<>(holder);
    Assertions.assertSame(holder, value.grantTypesJson("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getGrantTypesJsonValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getGrantTypesJson().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.grantTypesJsonNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getGrantTypesJsonValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getGrantTypesJson().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of grant types json of oauth client")
  void test_grant_types_json_value_holder_assign_value_object() {
    Object holder = new Object();
    GrantTypesJsonValueHolder<Object> value = new GrantTypesJsonValueHolder<>(holder);
    GrantTypesJsonVO vo = GrantTypesJsonVO.from("one");
    Assertions.assertFalse(value.getGrantTypesJsonValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.grantTypesJson(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getGrantTypesJsonValue().orElseThrow());
    Assertions.assertSame(holder, value.grantTypesJson(Optional.empty()));
    Assertions.assertFalse(value.getGrantTypesJsonValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.grantTypesJson(Optional.of(vo)));
    Assertions.assertSame(vo, value.getGrantTypesJsonValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of grant types json of oauth client against the original")
  void test_grant_types_json_value_holder_read() {
    Object holder = new Object();
    GrantTypesJsonValueHolder<Object> value = new GrantTypesJsonValueHolder<>(holder);
    GrantTypesJsonVO vo = GrantTypesJsonVO.from("one");
    GrantTypesJsonVO other = GrantTypesJsonVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getGrantTypesJsonValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readGrantTypesJson(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readGrantTypesJson(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.grantTypesJson(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readGrantTypesJson(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readGrantTypesJson(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of grant types json of oauth client")
  void test_grant_types_json_value_holder_unset() {
    Object holder = new Object();
    GrantTypesJsonValueHolder<Object> value = new GrantTypesJsonValueHolder<>(holder);
    GrantTypesJsonVO vo = GrantTypesJsonVO.from("one");
    value.grantTypesJson(vo);
    Assertions.assertSame(holder, value.unsetGrantTypesJsonIfMatches("grantTypesJson_other"));
    Assertions.assertTrue(value.getGrantTypesJsonValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetGrantTypesJsonIfMatches("grantTypesJson"));
    Assertions.assertFalse(value.getGrantTypesJsonValue().isPresent(),
        "The field name must clear the value");
    value.grantTypesJson(vo);
    Assertions.assertSame(holder, value.unsetGrantTypesJson());
    Assertions.assertFalse(value.getGrantTypesJsonValue().isPresent(),
        "Unset must clear the value");
  }
}
